                # from ansible_collections.ns.coll.plugins.module_utils.MODULE import IDENTIFIER [as aname]
                # FIXME: Unhandled cornercase (needs to be ignored):
                # from ansible_collections.ns.coll.plugins.[!module_utils].[FOO].plugins.module_utils import IDENTIFIER
                py_mod = tuple(node_module.split('.'))
            else:
                # Not from module_utils so ignore.  for instance:
                # from ansible_collections.ns.coll.plugins.lookup import IDENTIFIER
                pass

        if py_mod:
            for alias in node.names:
                submodule = py_mod + tuple(alias.name.split('.'))
                self.submodules.add(submodule)
                # A from-import leaf can be a module or an attribute. Only
                # consider the module-vs-attribute ambiguity below a package
                # level; imports directly from module_utils are unambiguous.
                if node_module.startswith('ansible.module_utils.'):
                    depth = len(node_module.split('.')) - 2
                elif '.plugins.module_utils' in node_module:
                    depth = len(node_module.split('.')) - node_module.split('.').index('module_utils') - 1
                else:
                    depth = 0
                if depth > 0:
                    depth += len(alias.name.split('.'))
                if depth > 1:
                    self.ambiguous_submodules.add(submodule)

        self.generic_visit(node)


def _slurp(path):
    if not os.path.exists(path):
        raise AnsibleError("imported module support code does not exist at %s" % os.path.abspath(path))
    with open(path, 'rb') as fd:
        data = fd.read()
    return data


def _get_shebang(interpreter, task_vars, templar, args=tuple()):
    """
    Note not stellar API:
       Returns None instead of always returning a shebang line.  Doing it this
       way allows the caller to decide to use the shebang it read from the
       file rather than trust that we reformatted what they already have
       correctly.
    """
    interpreter_name = os.path.basename(interpreter).strip()

    # FUTURE: add logical equivalence for python3 in the case of py3-only modules

    # check for first-class interpreter config
    interpreter_config_key = "INTERPRETER_%s" % interpreter_name.upper()

    if C.config.get_configuration_definitions().get(interpreter_config_key):
        # a config def exists for this interpreter type; consult config for the value
        interpreter_out = C.config.get_config_value(interpreter_config_key, variables=task_vars)
        discovered_interpreter_config = u'discovered_interpreter_%s' % interpreter_name

        interpreter_out = templar.template(interpreter_out.strip())

        facts_from_task_vars = task_vars.get('ansible_facts', {})

        # handle interpreter discovery if requested
        if interpreter_out in ['auto', 'auto_legacy', 'auto_silent', 'auto_legacy_silent']:
            if discovered_interpreter_config not in facts_from_task_vars:
                # interpreter discovery is desired, but has not been run for this host
                raise InterpreterDiscoveryRequiredError("interpreter discovery needed",
                                                        interpreter_name=interpreter_name,
                                                        discovery_mode=interpreter_out)
            else:
                interpreter_out = facts_from_task_vars[discovered_interpreter_config]
    else:
        # a config def does not exist for this interpreter type; consult vars for a possible direct override
        interpreter_config = u'ansible_%s_interpreter' % interpreter_name

        if interpreter_config not in task_vars:
            return None, interpreter

        interpreter_out = templar.template(task_vars[interpreter_config].strip())

    shebang = u'#!' + interpreter_out

    if args:
        shebang = shebang + u' ' + u' '.join(args)

    return shebang, interpreter_out


class ModuleInfo:
    def __init__(self, name, paths):
        self.py_src = False
        self.pkg_dir = False
        self.namespace_package = False
        path = None

        if imp is None:
            # don't pretend this is a top-level module, prefix the rest of the namespace
            self._info = info = importlib.machinery.PathFinder.find_spec('ansible.module_utils.' + name, paths)
            if info is not None:
                if info.origin is None:
                    self.py_src = True
                    self.pkg_dir = True
                    self.namespace_package = True
                    path = os.path.join(next(iter(info.submodule_search_locations)), '__init__.py')
                else:
                    self.py_src = os.path.splitext(info.origin)[1] in importlib.machinery.SOURCE_SUFFIXES
                    self.pkg_dir = info.origin.endswith('/__init__.py')
                    path = info.origin
            else:
                raise ImportError("No module named '%s'" % name)
        else:
            self._info = info = imp.find_module(name, paths)
            self.py_src = info[2][2] == imp.PY_SOURCE
            self.pkg_dir = info[2][2] == imp.PKG_DIRECTORY
            if self.pkg_dir:
                path = os.path.join(info[1], '__init__.py')
            else:
                path = info[1]

        self.path = path

    def get_source(self):
        if self.namespace_package:
            return b''
        if imp and self.py_src:
            try:
                return self._info[0].read()
            finally:
                self._info[0].close()
        return _slurp(self.path)

    def __repr__(self):
        return 'ModuleInfo: py_src=%s, pkg_dir=%s, path=%s' % (self.py_src, self.pkg_dir, self.path)


class CollectionModuleInfo(ModuleInfo):
    def __init__(self, name, pkg):
        self._mod_name = name
        self.py_src = True
        self.pkg_dir = False

        split_name = pkg.split('.')
        split_name.append(name)
        if len(split_name) < 5 or split_name[0] != 'ansible_collections' or split_name[3] != 'plugins' or split_name[4] != 'module_utils':
            raise ValueError('must search for something beneath a collection module_utils, not {0}.{1}'.format(to_native(pkg), to_native(name)))

        # NB: we can't use pkgutil.get_data safely here, since we don't want to import/execute package/module code on
        # the controller while analyzing/assembling the module, so we'll have to manually import the collection's
        # Python package to locate it (import root collection, reassemble resource path beneath, fetch source)

        collection_pkg_name = '.'.join(split_name[0:3])
        resource_base_path = os.path.join(*split_name[3:])
        self.path = os.path.join(collection_pkg_name, resource_base_path)
        self._src = pkgutil.get_data(collection_pkg_name, to_native(os.path.join(resource_base_path, '__init__.py')))
        if self._src is not None:
            self.pkg_dir = True
            self.path = os.path.join(collection_pkg_name, resource_base_path, '__init__.py')
            return

        self._src = pkgutil.get_data(collection_pkg_name, to_native(resource_base_path + '.py'))
        if self._src is None:
            raise ImportError('unable to load collection-hosted module_util'
                              ' {0}.{1}'.format(to_native(pkg), to_native(name)))
        self.path += '.py'

    def get_source(self):
        return self._src


class InternalRedirectModuleInfo(ModuleInfo):
    def __init__(self, name, full_name, redirect=None):
        self.pkg_dir = False
        self._original_name = full_name
        self.path = full_name.replace('.', '/') + '.py'
        if redirect is None:
            collection_meta = _get_collection_metadata('ansible.builtin')
            redirect = collection_meta.get('plugin_routing', {}).get('module_utils', {}).get(name, {}).get('redirect')
        if not redirect:
            raise ImportError('no redirect found for {0}'.format(name))
        self._redirect = _expand_module_utils_redirect(redirect)
        _validate_module_utils_redirect_target(self._redirect)
        self.py_src = True
        self._shim_src = (
            'import sys\n'
            'import {0} as _redirected_module\n'
            'sys.modules[__name__] = _redirected_module\n'
        ).format(self._redirect)

    def get_source(self):
        return to_bytes(self._shim_src)


def _expand_module_utils_redirect(redirect):
    """Return the Python import path for a module_utils routing target."""
    redirect = to_native(redirect)
    if redirect.startswith('ansible_collections.'):
        return redirect
    if redirect.startswith('ansible.module_utils.'):
        return redirect

    parts = redirect.split('.')
    if len(parts) >= 5 and parts[2:4] == ['plugins', 'module_utils']:
        return 'ansible_collections.' + redirect
    if len(parts) >= 3:
        # Collection FQCRs use ns.coll.resource[.submodule], with the plugin
        # type supplied by the loader. For module_utils that is this path.
        return 'ansible_collections.{0}.{1}.plugins.module_utils.{2}'.format(
            parts[0], parts[1], '.'.join(parts[2:]))
    return redirect


def _validate_module_utils_redirect_target(redirect):
    if not redirect.startswith('ansible_collections.'):
        return
    parts = redirect.split('.')
    if len(parts) < 3:
        return
    collection_name = '.'.join(parts[1:3])
    try:
        __import__('ansible_collections.' + collection_name, fromlist=['__path__'])
    except ImportError:
        raise AnsibleError('unable to locate collection {0}'.format(collection_name))


class ModuleUtilLocatorBase:
    """Resolve a module_utils import and describe the files for the payload."""

    module_utils_prefix = ()
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False,
                 redirect_first=None):
        self.fq_name_parts = tuple(fq_name_parts)
        self.child_is_redirected = child_is_redirected
        self.redirect_first = self.redirect_first if redirect_first is None else redirect_first
        self.is_ambiguous = bool(is_ambiguous and self._module_utils_depth() > 1)
        self.found = False
        self.redirected = False
        self.normalized_name_parts = None
        self.is_package = False
        self.output_path = None
        self.source_path = None
        self.source_code = None
        self.module_info = None
        self.resolved_files = []
        self._resolve()

    def _module_utils_depth(self):
        if self.fq_name_parts[:len(self.module_utils_prefix)] == self.module_utils_prefix:
            return len(self.fq_name_parts) - len(self.module_utils_prefix)
        return 0

    def _candidate_parts(self):
        candidates = [self.fq_name_parts]
        if self.is_ambiguous:
            candidates.append(self.fq_name_parts[:-1])
        return candidates

    def candidate_names_joined(self):
        return ['.'.join(parts) for parts in self._candidate_parts()]

    def _resolve(self):
        raise NotImplementedError

    def _set_result(self, name_parts, source, path, is_package=False, redirected=False, module_info=None):
        self.found = True
        self.redirected = redirected
        self.normalized_name_parts = tuple(name_parts) + (('__init__',) if is_package else ())
        self.is_package = is_package
        self.output_path = '/'.join(self.normalized_name_parts) + '.py'
        self.source_path = path
        self.source_code = source
        self.module_info = module_info
        self.resolved_files = [(self.normalized_name_parts, source, path)]


def _module_utils_route(collection_name, resource_name):
    try:
        metadata = _get_collection_metadata(collection_name)
    except (ImportError, ValueError) as exc:
        raise AnsibleError(to_native(exc))
    return metadata.get('plugin_routing', {}).get('module_utils', {}).get(resource_name, {})


def _process_module_utils_route(route, fq_name, collection_name):
    deprecation = route.get('deprecation')
    if deprecation:
        warning_text = deprecation.get('warning_text') or '{0} is deprecated'.format(fq_name)
        display.deprecated(warning_text, version=deprecation.get('removal_version'),
                           date=deprecation.get('removal_date'), collection_name=collection_name)

    tombstone = route.get('tombstone')
    if tombstone:
        warning_text = tombstone.get('warning_text') or '{0} has been removed'.format(fq_name)
        removal_date = tombstone.get('removal_date')
        removal_version = tombstone.get('removal_version')
        message = display.get_deprecation_message(warning_text, version=removal_version,
                                                  date=removal_date, collection_name=collection_name,
                                                  removed=True)
        raise AnsibleError(message)


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    module_utils_prefix = ('ansible', 'module_utils')
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None,
                 child_is_redirected=False, redirect_first=None):
        self.mu_paths = mu_paths
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous,
                                                      child_is_redirected, redirect_first)

    def _paths_for(self, relative_parts):
        paths = self.mu_paths
        if paths is None:
            paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
            paths.append(_MODULE_UTILS_PATH)
        return [os.path.join(path, *relative_parts[:-1]) for path in paths]

    def _route(self, relative_parts):
        depths = (len(relative_parts),) if self.is_ambiguous and not self.redirect_first else range(len(relative_parts), 0, -1)
        for depth in depths:
            resource_name = '.'.join(relative_parts[:depth])
            try:
                route = _module_utils_route('ansible.builtin', resource_name)
            except AnsibleError:
                return {}
            if route:
                route = dict(route)
                suffix = '.'.join(relative_parts[depth:])
                if suffix and route.get('redirect'):
                    route['redirect'] = route['redirect'] + '.' + suffix
                return route
        return {}

    def _resolve_candidate(self, candidate):
        relative_parts = candidate[len(self.module_utils_prefix):]
        if not relative_parts:
            return False
        route = self._route(relative_parts)
        if route.get('tombstone'):
            _process_module_utils_route(route, '.'.join(candidate), 'ansible.builtin')
        if self.redirect_first and route.get('redirect'):
            return self._set_redirect(candidate, route, relative_parts)

        try:
            info = ModuleInfo(relative_parts[-1], self._paths_for(relative_parts))
        except (ImportError, IOError, OSError):
            info = None
        if info is not None:
            if not info.pkg_dir and not info.py_src:
                return False
            self._set_result(candidate, info.get_source(), info.path, info.pkg_dir, module_info=info)
            self._add_parent_packages(relative_parts)
            return True

        if route.get('redirect'):
            redirected = self._set_redirect(candidate, route, relative_parts)
            if redirected:
                self._add_parent_packages(relative_parts)
            return redirected
        return False

    def _set_redirect(self, candidate, route, relative_parts):
        _process_module_utils_route(route, '.'.join(candidate), 'ansible.builtin')
        target = route.get('redirect')
        if not target:
            return False
        info = InternalRedirectModuleInfo('.'.join(relative_parts), '.'.join(candidate), target)
        self._set_result(candidate, info.get_source(), info.path, redirected=True, module_info=info)
        return True

    def _add_parent_packages(self, relative_parts):
        paths = self.mu_paths
        if paths is None:
            paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
            paths.append(_MODULE_UTILS_PATH)
        for depth in range(1, len(relative_parts)):
            package_parts = relative_parts[:depth]
            package_fqn = self.module_utils_prefix + package_parts + ('__init__',)
            if any(name == package_fqn for name, _source, _path in self.resolved_files):
                continue
            try:
                info = ModuleInfo(package_parts[-1], [os.path.join(p, *package_parts[:-1]) for p in paths])
                if not info.pkg_dir or not info.py_src:
                    continue
                source, path = info.get_source(), info.path
            except (ImportError, IOError, OSError):
                source, path = b'', '/'.join(self.module_utils_prefix + package_parts)
            self.resolved_files.append((package_fqn, source, path))

    def _resolve(self):
        for candidate in self._candidate_parts():
            if self._resolve_candidate(candidate):
                return


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    module_utils_prefix = ()
    redirect_first = True

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False,
                 redirect_first=None):
        self._collection_name = '.'.join(tuple(fq_name_parts)[1:3])
        self._collection_pkg_name = '.'.join(tuple(fq_name_parts)[:3])
        self._base_prefix = tuple(fq_name_parts)[:5]
        self.module_utils_prefix = self._base_prefix
        self._routing_metadata = None
        super(CollectionModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous,
                                                         child_is_redirected, redirect_first)

    def _get_routing_metadata(self):
        if self._routing_metadata is None:
            try:
                self._routing_metadata = _get_collection_metadata(self._collection_name)
            except (ImportError, ValueError) as exc:
                self._routing_metadata = {}
                self._collection_error = to_native(exc)
        return self._routing_metadata

    def _route(self, candidate):
        relative_parts = candidate[len(self._base_prefix):]
        metadata = self._get_routing_metadata()
        routes = metadata.get('plugin_routing', {}).get('module_utils', {})
        for depth in range(len(relative_parts), 0, -1):
            resource_name = '.'.join(relative_parts[:depth])
            route = routes.get(resource_name, {})
            if route:
                route = dict(route)
                suffix = '.'.join(relative_parts[depth:])
                if suffix and route.get('redirect'):
                    route['redirect'] = route['redirect'] + '.' + suffix
                return route
        return {}

    def _collection_data(self, resource_path):
        try:
            return pkgutil.get_data(self._collection_pkg_name, to_native(resource_path))
        except (ImportError, IOError, OSError, ValueError):
            return None

    def _resolve_candidate(self, candidate):
        if candidate[:5] != self._base_prefix:
            return False
        relative_parts = candidate[len(self._base_prefix):]
        route = self._route(candidate)
        if route.get('tombstone'):
            _process_module_utils_route(route, '.'.join(candidate), self._collection_name)
        if self.redirect_first and route.get('redirect'):
            return self._set_redirect(candidate, route)

        if not relative_parts:
            source = self._collection_data('plugins/module_utils/__init__.py')
            if source is not None:
                self._set_result(candidate, source, self._collection_pkg_name + '/plugins/module_utils/__init__.py',
                                 is_package=True)
                self._add_parent_packages(candidate)
                return True
            return False

        resource_path = os.path.join('plugins', 'module_utils', *relative_parts)
        init_path = os.path.join(resource_path, '__init__.py')
        source = self._collection_data(init_path)
        if source is not None:
            path = self._collection_pkg_name + '/' + init_path
            self._set_result(candidate, source, path, is_package=True)
            self._add_parent_packages(candidate)
            return True

        source = self._collection_data(resource_path + '.py')
        if source is not None:
            path = self._collection_pkg_name + '/' + resource_path + '.py'
            self._set_result(candidate, source, path)
            self._add_parent_packages(candidate)
            return True

        if route.get('redirect'):
            return self._set_redirect(candidate, route)
        return False

    def _set_redirect(self, candidate, route):
        _process_module_utils_route(route, '.'.join(candidate), self._collection_name)
        target = route.get('redirect')
        if not target:
            return False
        expanded_target = _expand_module_utils_redirect(target)
        info = InternalRedirectModuleInfo('.'.join(candidate), '.'.join(candidate), expanded_target)
        self._set_result(candidate, info.get_source(), info.path, redirected=True, module_info=info)
        self._add_parent_packages(candidate)
        return True

    def _add_parent_packages(self, candidate):
        # Collection packages below the collection root can have real
        # initializers or be implicit namespace packages. Include each level
        # either way so the generated zip has a complete import hierarchy.
        relative_parts = candidate[3:]
        package_depth = len(relative_parts) if self.is_package else len(relative_parts) - 1
        for depth in range(1, package_depth + 1):
            package_parts = relative_parts[:depth]
            package_fqn = candidate[:3] + package_parts + ('__init__',)
            if any(name == package_fqn for name, _source, _path in self.resolved_files):
                continue
            resource_path = os.path.join(*package_parts, '__init__.py')
            source = self._collection_data(resource_path)
            if source is None:
                source = b''
            path = self._collection_pkg_name + '/' + resource_path
            self.resolved_files.append((package_fqn, source, path))

    def _resolve(self):
        for candidate in self._candidate_parts():
            if self._resolve_candidate(candidate):
                return


def _locator_for_import(fq_name_parts, ambiguous=False, mu_paths=None, child_is_redirected=False):
    if fq_name_parts[:2] == ('ansible', 'module_utils'):
        return LegacyModuleUtilLocator(fq_name_parts, ambiguous, mu_paths, child_is_redirected)
    if (fq_name_parts[:1] == ('ansible_collections',) and len(fq_name_parts) >= 5 and
            fq_name_parts[3:5] == ('plugins', 'module_utils')):
        return CollectionModuleUtilLocator(fq_name_parts, ambiguous, child_is_redirected)
    return None


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    """Queue and bundle all module_utils dependencies of a module."""
    module_utils_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    module_utils_paths.append(_MODULE_UTILS_PATH)
    queue = [(name, module_fqn, data)]
    scheduled = set(py_module_names)

    def enqueue_files(locator):
        for module_name, source, source_path in locator.resolved_files:
            if module_name in scheduled:
                continue
            scheduled.add(module_name)
            py_module_names.add(module_name)
            py_module_cache[module_name] = (source, source_path)
            archive_name = '/'.join(module_name) + '.py'
            zf.writestr(archive_name, source)
            queue.append((module_name[-1], '.'.join(module_name), source))
            display.vvvvv("Using module_utils file %s" % to_text(source_path, errors='surrogate_or_strict'))

    # Keep basic available for the wrapper's argument injection even when the
    # module itself does not import it.
    basic_name = ('ansible', 'module_utils', 'basic')
    if basic_name not in scheduled:
        basic_info = ModuleInfo('basic', module_utils_paths)
        py_module_cache[basic_name] = (basic_info.get_source(), basic_info.path)
        basic_locator = LegacyModuleUtilLocator(basic_name, mu_paths=module_utils_paths)
        # The basic module is always a module, regardless of mocks or unusual
        # import finders reporting it as a package.
        basic_locator.resolved_files = [(basic_name, basic_info.get_source(), basic_info.path)]
        enqueue_files(basic_locator)

    while queue:
        current_name, current_fqn, current_data = queue.pop(0)
        try:
            tree = compile(current_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as exc:
            raise AnsibleError("Unable to import %s due to %s" % (current_name, exc.msg))

        finder = ModuleDepFinder(current_fqn)
        finder.visit(tree)
        for imported_name in sorted(finder.submodules):
            if imported_name == ('_six',):
                imported_name = ('ansible', 'module_utils', 'six')
                ambiguous = False
            else:
                ambiguous = imported_name in finder.ambiguous_submodules

            # six implements its own import machinery. Ship only the base
            # module for all six submodule spellings.
            if imported_name[:3] == ('ansible', 'module_utils', 'six'):
                imported_name = ('ansible', 'module_utils', 'six')
                ambiguous = False
            elif imported_name[:3] == ('ansible', 'module_utils', '_six'):
                imported_name = ('ansible', 'module_utils', 'six')
                ambiguous = False

            locator = _locator_for_import(imported_name, ambiguous, module_utils_paths)
            if locator is None:
                display.warning('ModuleDepFinder improperly found a non-module_utils import %s' % [imported_name])
                continue
            if not locator.found:
                candidates = locator.candidate_names_joined()
                raise AnsibleError('Could not find imported module support code for {0}. Looked for ({1})'.format(
                    '.'.join(imported_name), candidates))
            enqueue_files(locator)
        # The current file has now been scanned; release its cached source.
        if current_fqn:
            current_key = tuple(current_fqn.split('.'))
            py_module_cache.pop(current_key, None)

    py_module_cache.pop(basic_name, None)


def _is_binary(b_module_data):
    textchars = bytearray(set([7, 8, 9, 10, 12, 13, 27]) | set(range(0x20, 0x100)) - set([0x7f]))
    start = b_module_data[:1024]
    return bool(start.translate(None, textchars))
